class Solution:
    def compare(self, freq: Counter[str], bar: Counter[str]) -> bool:
        for k, v in bar.items():
            if freq[k] < v:
                return False
        return True

    def minWindow(self, s: str, t: str) -> str:
        freq = defaultdict(int)
        for c in t:
            freq[c] = 0
        bar = Counter(t)
        ans = ""
        best = float("Inf")
        l = 0

        for r in range(len(s)):
            if s[r] in freq:
                freq[s[r]] += 1

            while self.compare(freq, bar):
                currSize = r - l + 1
                if best > currSize:
                    best = currSize
                    ans = s[l:r+1]

                if s[l] in freq:
                    freq[s[l]] -= 1
                l += 1

        return ans
